 "content": "def transform(grid):
    """Color the midpoint between neighboring equal non-background markers with 2."""
    from collections import Counter
    out = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        markers = [c for c, value in enumerate(row) if value != background]
        for left, right in zip(markers, markers[1:]):
            if right - left == 2 and row[left] == row[right]:
                out[r][left + 1] = 2
    return out

if __name__ == "__main__":
    # Demo pair 1
    demo1 = [[7] * 25 for _ in range(13)]
    for c in (4, 6, 8):
        demo1[4][c] = 1
    for c in (8, 10):
        demo1[10][c] = 1
    expected1 = [[7] * 25 for _ in range(13)]
    for c in (4, 6, 8):
        expected1[4][c] = 1
    for c in (5, 7):
        expected1[4][c] = 2
    for c in (8, 10):
        expected1[10][c] = 1
    expected1[10][9] = 2
    assert transform(demo1) == expected1

    # Demo pair 2
    demo2 = [[4] * 5 for _ in range(14)]
    for r in (2, 3):
        demo2[r][1] = demo2[r][3] = 1
    demo2[6][1] = demo2[6][3] = 1
    for r in (8, 9):
        demo2[r][0] = demo2[r][2] = 1
    demo2[12][0] = demo2[12][2] = 1
    expected2 = [row[:] for row in demo2]
    for r, c in ((2, 2), (3, 2), (6, 2), (8, 1), (9, 1), (12, 1)):
        expected2[r][c] = 2
    assert transform(demo2) == expected2
    print("Both demo pairs reproduced.")
